UNION ALL SELECT id, 'B', 'misconception', $a72B$Assumes a 1:1 MnO4-:C2O4^2- mole ratio, ignoring the redox electron balance$a72B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a72C$Inverts the 2:5 ratio, scaling titrant moles by 2/5 instead of 5/2$a72C$ FROM q;

